import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect, vi, beforeAll, afterAll } from "vitest";
import { screen, render } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import dayjs from "dayjs";
import TimeFramePicker from "../TimeFramePicker";
import { RDSConfigProvider } from "../../../rdsConfigProvider";
import { RDSThemeProvider, THEME_MODES } from "../../../rdsThemeProvider";
import { TIME_FRAME_UNITS } from "../constants";
describe("<TimeFramePicker />", () => {
    const presets = [
        {
            label: "Last 20 minutes",
            onParse: (now) => ({
                from: now.subtract(20, "minute").valueOf(),
                timeFrame: "Last 20 minutes",
                to: now.valueOf(),
            }),
        },
        {
            label: "Last 1 hour",
            onParse: (now) => ({
                from: now.subtract(1, "hour").valueOf(),
                timeFrame: "Last 1 hour",
                to: now.valueOf(),
            }),
        },
        {
            label: "Yesterday",
            onParse: (now) => ({
                from: now.startOf("day").subtract(1, "day").valueOf(),
                timeFrame: "Yesterday",
                to: now.startOf("day").subtract(1, "day").endOf("day").valueOf(),
            }),
        },
        {
            label: "Today",
            onParse: (now) => ({
                from: now.startOf("day").valueOf(),
                timeFrame: "Today",
                to: now.valueOf(),
            }),
        },
        {
            label: "Last 1 week",
            onParse: (now) => ({
                from: now.startOf("day").subtract(1, "week").valueOf(),
                timeFrame: "Last 1 week",
                to: now.valueOf(),
            }),
        },
        {
            label: "Last 30 days",
            onParse: (now) => ({
                from: now.subtract(30, "day").valueOf(),
                timeFrame: "Last 30 days",
                to: now.valueOf(),
            }),
        },
    ];
    const groupedPresets = [{ presets }];
    const now = dayjs("1 January 2025").startOf("day");
    beforeAll(() => {
        vi.useFakeTimers();
        vi.setSystemTime(now.toDate());
    });
    afterAll(() => {
        vi.useRealTimers();
    });
    it("uses 'UTC' timezone by default", () => {
        // Exercise SUT
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "UTC", now: now, onChange: vi.fn(), onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: "" }) }) }));
        // Verify results
        expect(screen.getByText("UTC+00:00"));
    });
    it("defaults to UTC when an invalid timezone is provided", () => {
        // Exercise SUT
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "Bad/Ting", now: now, onChange: vi.fn(), onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: "" }) }) }));
        // Verify results
        expect(screen.getByText("UTC+00:00"));
    });
    it("shows the provided timezone in the correct format when one is provided", () => {
        // Exercise SUT
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "America/Havana", now: now, onChange: vi.fn(), onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: "" }) }) }));
        // Verify results
        expect(screen.getByText("UTC-05:00"));
    });
    it("shows all the provided preset groups when multiple are provided", () => {
        // Setup fixture
        const groupedPresets = [
            {
                presets,
                title: "Relative",
            },
            {
                presets: [
                    {
                        label: "January",
                        value: {
                            from: dayjs("1 January 2025").startOf("day").valueOf(),
                            to: dayjs("31 January 2025").endOf("day").valueOf(),
                        },
                    },
                ],
                title: "Months",
            },
        ];
        // Exercise SUT
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "America/Havana", now: now, onChange: vi.fn(), onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: "" }) }) }));
        // Verify results
        expect(screen.getByText("Relative")).toBeInTheDocument();
        expect(screen.getByText("Months")).toBeInTheDocument();
        expect(screen.getByText("Last 20 minutes")).toBeInTheDocument();
        expect(screen.getByText("January")).toBeInTheDocument();
    });
    it("preselects the preset matching the provided value when it matches the provided presets", () => {
        // Setup fixture
        const value = "Last 30 days";
        // Exercise SUT
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "America/Havana", now: now, onChange: vi.fn(), onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: value }) }) }));
        // Verify results
        expect(screen.getByTestId("selected-preset").textContent).toBe(value);
    });
    it("does not preselect any preset if the provided value does not match the provided presets", () => {
        // Setup fixture
        const value = "Last 666 days";
        // Exercise SUT
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "UTC", now: now, onChange: vi.fn(), onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: value }) }) }));
        // Verify results
        expect(screen.queryByTestId("selected-preset")).not.toBeInTheDocument();
    });
    it("deselects the selected preset when the custom preset value is updated", async () => {
        // Setup fixture
        const value = "Last 30 days";
        const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
        // Exercise SUT
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "UTC", now: now, onChange: vi.fn(), onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: value }) }) }));
        // Exercise SUT
        await user.type(screen.getByPlaceholderText("#"), "12");
        // Verify results
        expect(screen.queryByTestId("selected-preset")).not.toBeInTheDocument();
    });
    it("returns the correct time range when an existing preset is chosen", async () => {
        // Setup fixture
        const onChangeSpy = vi.fn();
        const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "Asia/Jakarta", now: now, onChange: onChangeSpy, onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: "" }) }) }));
        // Exercise SUT
        await user.click(screen.getByText("Yesterday"));
        await user.click(screen.getByText("Ok"));
        // Verify results
        expect(onChangeSpy).toHaveBeenCalledWith({
            from: now.clone().subtract(1, "day").startOf("day").valueOf(),
            timeFrame: "Yesterday",
            to: now.clone().subtract(1, "day").endOf("day").valueOf(),
        });
    });
    it("returns the correct time range when an existing preset in a second group is chosen", () => {
        // Setup fixture
        const onChangeSpy = vi.fn();
        const groupedPresets = [
            {
                presets,
                title: "Relative",
            },
            {
                presets: [
                    {
                        label: "January",
                        value: {
                            from: dayjs("1 January 2025").startOf("day").valueOf(),
                            to: dayjs("31 January 2025").endOf("day").valueOf(),
                        },
                    },
                ],
                title: "Months",
            },
        ];
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: presets, groupedPresets: groupedPresets, hasCustomRange: true, ianaTimezone: "America/Havana", now: now, onChange: onChangeSpy, onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: "" }) }) }));
        // Exercise SUT
        screen.getByText("January").click();
        // Verify results
        expect(onChangeSpy).toHaveBeenCalledWith({
            from: dayjs("1 January 2025").startOf("day").valueOf(),
            timeFrame: "January",
            to: dayjs("31 January 2025").endOf("day").valueOf(),
        });
    });
    it("returns the correct time range when a custom time range is chosen", async () => {
        // Setup fixture
        const onChangeSpy = vi.fn();
        const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
        const localNow = dayjs.tz("1 January 2025", "Asia/Riyadh");
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: [], groupedPresets: [], hasCustomRange: true, ianaTimezone: "Asia/Riyadh", now: localNow, onChange: onChangeSpy, onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: "" }) }) }));
        // Exercise SUT
        await user.type(screen.getByPlaceholderText("#"), "12");
        await user.click(screen.getByLabelText("Unit of time"));
        await user.click(document.querySelectorAll(".MuiMenuItem-root")[2]);
        await user.click(screen.getByText("Ok"));
        // Verify results
        expect(onChangeSpy).toHaveBeenCalledWith({
            from: localNow.clone().subtract(12, "hours").valueOf(),
            timeFrame: "Last 12 hours",
            to: localNow.valueOf(),
        });
    });
    it("returns the correct pluralization when a custom time range is chosen", async () => {
        // Setup fixture
        const onChangeSpy = vi.fn();
        const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
        const localNow = dayjs.tz("1 January 2025", "Africa/Lagos");
        render(_jsx(RDSThemeProvider, { themeMode: THEME_MODES.LIGHT, children: _jsx(RDSConfigProvider, { children: _jsx(TimeFramePicker, { flattenedPresets: [], groupedPresets: [], hasCustomRange: true, ianaTimezone: "Africa/Lagos", now: localNow, onChange: onChangeSpy, onSubmit: vi.fn(), units: TIME_FRAME_UNITS, value: "" }) }) }));
        // Exercise SUT
        await user.type(screen.getByPlaceholderText("#"), "1");
        await user.click(screen.getByLabelText("Unit of time"));
        await user.click(document.querySelectorAll(".MuiMenuItem-root")[3]);
        await user.click(screen.getByText("Ok"));
        // Verify results
        expect(onChangeSpy).toHaveBeenCalledWith({
            from: localNow.clone().subtract(1, "day").valueOf(),
            timeFrame: "Last 1 day",
            to: localNow.valueOf(),
        });
    });
});
